// Return log result
const logResult = $input.item.json;

return {
  logged: true,
  logId: logResult?.id
};

// WF-60 Step 2: Normalize input to canonical shape; compute filter & lookup flags.
const input = $input.first().json;

const direction = input.direction || 'inbound';
const messageType = input.messageType || 'text';
const content = input.content ?? input.messageContent ?? input.userMessage ?? null;
const userId = input.userId ?? input.user?.id ?? null;
const consultationId = input.consultationId ?? input.user?.current_consultation_id ?? null;
const whatsappMessageId = input.whatsappMessageId ?? input.messageId ?? null;
const phoneNumber = input.phoneNumber ?? input.phoneNumberFormatted ?? input.metadata?.phoneNumber ?? null;

// TD-034 whitespace guard (inbound text only).
let filterReason = null;
if (direction === 'inbound' && messageType === 'text') {
  const trimmed = (content == null ? '' : String(content).trim());
  if (trimmed.length === 0) filterReason = 'whitespace_only_filtered';
}

// Lookup needed only if not filtered, no userId, and a phoneNumber to look up.
const needsLookup = !filterReason && !userId && !!phoneNumber;

return [{
  json: {
    userId,
    consultationId,
    direction,
    messageType,
    content,
    whatsappMessageId,
    phoneNumber,
    _filterReason: filterReason,
    _needsLookup: needsLookup,
    metadata: {
      phoneNumber,
      rawMessage: input.rawMessage || null,
      timestamp: input.timestamp || new Date().toISOString(),
      contactName: input.contactName || null,
      success: input.success ?? null,
      error: input.error || null,
      inboundMessageId: input.inboundMessageId || null,
      sentAt: input.sentAt || null
    }
  }
}];

// WF-60 Step 4b — no userId resolved.
// Inbound (pre-onboarding pendingUser): return pre_onboarding_user (FK NOT NULL means we cannot insert).
// Outbound: caller didn't pass userId — return no_userId.
const row = $input.first().json;
const direction = row.direction || 'inbound';
if (direction === 'inbound') {
  return [{ json: { logged: false, reason: 'pre_onboarding_user' } }];
}
return [{ json: { logged: false, reason: 'no userId — caller did not provide user identification' } }];

// Filter triggered upstream (e.g. TD-034 whitespace) — return structured skip.
const row = $input.first().json;
return [{ json: { logged: false, reason: row._filterReason || 'filtered' } }];

// Merge phone-lookup result back into the extracted row before the userId gate.
const extracted = $('Extract Message Data').first().json;
const lookup = $input.first()?.json;
const hitId = lookup?.id || null;
const hitConsultation = lookup?.current_consultation_id || null;

return [{
  json: {
    ...extracted,
    userId: extracted.userId || hitId,
    consultationId: extracted.consultationId || hitConsultation
  }
}];

